import fs from 'node:fs'
import { fileURLToPath } from 'node:url'

// ───────── iqcwmp ─────────
// Meme "Windows Media Player" (Windows XP / Luna): teks tebal di kiri + tokoh 3D yang pusing di kanan.
// Semua digambar lokal pakai canvas, resolusi 2x (2160×2354), tanpa API luar.
//
//   .iqcwmp <teks>                   -> tema biru (bawaan)
//   .iqcwmp olive <teks>             -> tema Olive Green   (juga: hijau)
//   .iqcwmp silver <teks>            -> tema Silver        (juga: perak)
//   .iqcwmp <teks> | <judul jendela> -> ganti tulisan di title bar (bawaan "Windows Media Player")
//   kirim/reply foto + .iqcwmp <teks>-> foto menggantikan tokoh 3D di kanan
//   reply pesan + .iqcwmp            -> teks diambil dari pesan yang di-reply

const FONT_DIR = fileURLToPath(new URL('../../lib/store/fonts/', import.meta.url))
const FIGURE_B64 = '' // tokoh 3D (WebP transparan, sudah dibersihkan latarnya)

const SCALE = 2
const W = 1080, H = 1177
const TITLE_H = 106, MENU_Y = 106, MENU_H = 76, BAND_Y = 183, BAND_H = 40
const CONT_Y = 224, CONT_B = 952, STATUS_B = 1006, CTRL_B = 1150
const SIDE = 8

const THEMES = {
  blue: {
    title: [[0, '#4a9bff'], [0.05, '#2a79f5'], [0.18, '#0a5ae8'], [0.55, '#0553e0'], [0.9, '#0847d2'], [1, '#0a40c4']],
    frame: [[0, '#0a5be8'], [0.1, '#0654e0'], [0.9, '#0a3cc4'], [1, '#0830a8']],
    foot: [[0, '#2a4fc8'], [0.4, '#1a3cc0'], [1, '#0f2aa0']],
    btn: [[0, '#8fbcff'], [0.45, '#3a78ea'], [1, '#1a56cf']],
    band: ['#8196d6', '#5f78c2'], bandL: ['#f6f6f8', '#c8c9dc', '#8d8baa'],
    panel: [[0, '#a8c6fa'], [0.12, '#7c9ee0'], [0.45, '#6685c8'], [0.75, '#5c6dba'], [1, '#4a53a2']],
    track: '#7e9fd8', glyph: '#6a76a8', glyphDark: '#25306e', titleText: '#ffffff', titleShadow: 'rgba(0,20,100,0.65)'
  },
  olive: {
    title: [[0, '#c4d49a'], [0.05, '#aabd7c'], [0.18, '#92a666'], [0.55, '#8aa05b'], [0.9, '#7a8f4d'], [1, '#6e8342']],
    frame: [[0, '#93a863'], [0.1, '#869a58'], [0.9, '#6b7f3d'], [1, '#5d7133']],
    foot: [[0, '#7e9350'], [0.4, '#6c7f3f'], [1, '#566830']],
    btn: [[0, '#d6e2b4'], [0.45, '#9db26d'], [1, '#6f8641']],
    band: ['#b4c48a', '#8a9c5d'], bandL: ['#f8f9f0', '#d2dab6', '#98a272'],
    panel: [[0, '#dce6c0'], [0.12, '#c2d19a'], [0.45, '#aebf80'], [0.75, '#98aa6a'], [1, '#7e9051']],
    track: '#a7b97c', glyph: '#66793e', glyphDark: '#36451c', titleText: '#ffffff', titleShadow: 'rgba(40,55,10,0.7)'
  },
  silver: {
    title: [[0, '#dcdcec'], [0.05, '#c8c8de'], [0.18, '#adadca'], [0.55, '#a2a2c2'], [0.9, '#9494b6'], [1, '#8a8aae']],
    frame: [[0, '#c3c3d9'], [0.1, '#b6b6cf'], [0.9, '#9c9cbc'], [1, '#8c8cae']],
    foot: [[0, '#acacca'], [0.4, '#9898ba'], [1, '#7e7ea2']],
    btn: [[0, '#fbfbff'], [0.45, '#cfcfe4'], [1, '#9c9cba']],
    band: ['#c6c6dc', '#a4a4c4'], bandL: ['#fafafe', '#d8d8ea', '#9c9cba'],
    panel: [[0, '#f4f4fc'], [0.12, '#dedeec'], [0.45, '#c6c6dc'], [0.75, '#b1b1ce'], [1, '#9898ba']],
    track: '#b4b4ce', glyph: '#6f6f95', glyphDark: '#34345c', titleText: '#ffffff', titleShadow: 'rgba(30,30,80,0.9)'
  }
}
const THEME_ALIAS = { blue: 'blue', biru: 'blue', olive: 'olive', hijau: 'olive', silver: 'silver', perak: 'silver' }

// kotak dengan radius atas dan bawah berbeda
const rrTB = (ctx, x, y, w, h, rt, rb) => {
  ctx.beginPath()
  ctx.moveTo(x + rt, y)
  ctx.arcTo(x + w, y, x + w, y + h, rt)
  ctx.arcTo(x + w, y + h, x, y + h, rb)
  ctx.arcTo(x, y + h, x, y, rb)
  ctx.arcTo(x, y, x + w, y, rt)
  ctx.closePath()
}
const rr = (ctx, x, y, w, h, r) => rrTB(ctx, x, y, w, h, r, r)
const vg = (ctx, y0, y1, stops) => {
  const g = ctx.createLinearGradient(0, y0, 0, y1)
  for (const [o, c] of stops) g.addColorStop(o, c)
  return g
}

let figurePromise = null

let handler = async (m, { sock, text, reply, prefix, usedPrefix }) => {
  const p = usedPrefix ?? prefix ?? '.'

  // ── baca argumen: [tema] teks | judul ──
  let raw = String(text || '').trim()
  let themeKey = 'blue'
  const firstWord = raw.split(/\s+/)[0]?.toLowerCase()
  if (THEME_ALIAS[firstWord]) { themeKey = THEME_ALIAS[firstWord]; raw = raw.slice(firstWord.length).trim() }
  let [msgPart, ...titlePart] = raw.split('|')
  const winTitle = (titlePart.join('|').trim() || 'Windows Media Player').slice(0, 34)
  const message = (msgPart.trim() || m.quoted?.text || m.quoted?.caption || '').replace(/\s+/g, ' ').trim()

  if (!message) {
    return reply(
      `🪟 *IQC WMP (Windows Media Player)*\n\n` +
      `Meme jendela Windows Media Player XP.\n\n` +
      `• ${p}iqcwmp <teks>\n` +
      `• ${p}iqcwmp olive <teks> → tema hijau\n` +
      `• ${p}iqcwmp silver <teks> → tema perak\n` +
      `• ${p}iqcwmp <teks> | <judul> → ganti judul jendela\n` +
      `• kirim/reply foto + ${p}iqcwmp <teks> → foto ganti tokoh 3D\n` +
      `• reply pesan + ${p}iqcwmp → teks dari pesan itu\n\n` +
      `Contoh: ${p}iqcwmp padahal cuma std kirian`
    )
  }
  if (message.length > 120) return reply('❌ Teks terlalu panjang (maksimal 120 huruf).')

  let canvasLib
  try { canvasLib = await import('@napi-rs/canvas') } catch {
    return reply('❌ Fitur ini butuh @napi-rs/canvas, belum terpasang di server.')
  }
  const { createCanvas, loadImage, GlobalFonts } = canvasLib.default ?? canvasLib

  try {
    for (const f of ['Inter-Medium', 'Inter-SemiBold', 'Inter-Bold']) {
      try { if (fs.existsSync(`${FONT_DIR}${f}.ttf`)) GlobalFonts.registerFromPath(`${FONT_DIR}${f}.ttf`, 'IqcWin') } catch {}
    }
    const UI = '"Tahoma", "Segoe UI", "IqcWin", sans-serif'
    const TITLE = '"Trebuchet MS", "Tahoma", "IqcWin", sans-serif'
    const BIG = '"IqcWin", "Montserrat", "Poppins", "Arial Black", sans-serif'
    const T = THEMES[themeKey]

    // gambar kanan: foto user (kalau ada) atau tokoh 3D bawaan
    let userImg = null
    try {
      let buf = null
      if (m.quoted && /image/i.test(String(m.quoted.mtype || '')) && typeof m.quoted.download === 'function') buf = await m.quoted.download()
      else if (/image/i.test(String(m.mtype || '')) && typeof m.download === 'function') buf = await m.download()
      if (buf?.length) userImg = await loadImage(buf)
    } catch {}
    if (!userImg) figurePromise ||= loadImage(Buffer.from(FIGURE_B64, 'base64')).catch(() => null)
    const figure = userImg || await figurePromise

    const canvas = createCanvas(W * SCALE, H * SCALE)
    const ctx = canvas.getContext('2d')
    ctx.scale(SCALE, SCALE)
    ctx.imageSmoothingEnabled = true
    ctx.imageSmoothingQuality = 'high'

    const glossOn = (x, y, w, h, r, a = 0.55) => { // kilau kaca di separuh atas
      ctx.save(); rr(ctx, x, y, w, h, r); ctx.clip()
      const g = ctx.createLinearGradient(0, y, 0, y + h * 0.55)
      g.addColorStop(0, `rgba(255,255,255,${a})`); g.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = g; ctx.fillRect(x, y, w, h * 0.55); ctx.restore()
    }

    // ═════════ frame jendela ═════════
    ctx.save()
    rrTB(ctx, 0, 0, W, H, 26, 10); ctx.clip()
    ctx.fillStyle = vg(ctx, 0, H, T.frame); ctx.fillRect(0, 0, W, H)

    // title bar
    ctx.fillStyle = vg(ctx, 0, TITLE_H, T.title); ctx.fillRect(0, 0, W, TITLE_H)
    ctx.fillStyle = 'rgba(255,255,255,0.34)'; ctx.fillRect(0, 2, W, 2)
    ctx.fillStyle = 'rgba(255,255,255,0.12)'; ctx.fillRect(0, 4, W, 6)
    ctx.fillStyle = 'rgba(0,0,50,0.28)'; ctx.fillRect(0, TITLE_H - 2, W, 2)
    ctx.restore()
    // garis tepi luar jendela
    ctx.strokeStyle = 'rgba(0,0,60,0.55)'; ctx.lineWidth = 2; rrTB(ctx, 1, 1, W - 2, H - 2, 25, 9); ctx.stroke()

    // ikon WMP (bola oranye berkilau + cincin biru)
    const ic = { x: 42, y: 56 }
    ctx.fillStyle = '#0d3fb0'; ctx.beginPath(); ctx.arc(ic.x, ic.y, 27, 0, Math.PI * 2); ctx.fill()
    ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(ic.x, ic.y, 25, 0, Math.PI * 2); ctx.fill()
    const og = ctx.createRadialGradient(ic.x - 7, ic.y - 9, 2, ic.x, ic.y, 24)
    og.addColorStop(0, '#ffe3a0'); og.addColorStop(0.45, '#f59a22'); og.addColorStop(1, '#a84a00')
    ctx.fillStyle = og; ctx.beginPath(); ctx.arc(ic.x, ic.y, 22, 0, Math.PI * 2); ctx.fill()
    ctx.fillStyle = '#16226a'; ctx.beginPath(); ctx.moveTo(ic.x - 7, ic.y - 12); ctx.lineTo(ic.x + 14, ic.y); ctx.lineTo(ic.x - 7, ic.y + 12); ctx.closePath(); ctx.fill()
    const tg = ctx.createLinearGradient(0, ic.y - 8, 0, ic.y + 8); tg.addColorStop(0, '#f4fff8'); tg.addColorStop(1, '#8fe0a8')
    ctx.fillStyle = tg; ctx.beginPath(); ctx.moveTo(ic.x - 3, ic.y - 7); ctx.lineTo(ic.x + 8, ic.y); ctx.lineTo(ic.x - 3, ic.y + 7); ctx.closePath(); ctx.fill()
    ctx.fillStyle = 'rgba(255,255,255,0.5)'; ctx.beginPath(); ctx.ellipse(ic.x - 6, ic.y - 14, 10, 5, -0.5, 0, Math.PI * 2); ctx.fill()

    // judul (mengecil otomatis kalau panjang)
    let tsz = 46
    ctx.textAlign = 'left'; ctx.textBaseline = 'middle'
    for (; tsz > 24; tsz -= 2) { ctx.font = `700 ${tsz}px ${TITLE}`; if (ctx.measureText(winTitle).width <= 740) break }
    ctx.fillStyle = T.titleShadow; ctx.fillText(winTitle, 83, 65)
    ctx.fillStyle = T.titleText; ctx.fillText(winTitle, 80, 62)

    // tombol min / max / close
    const winBtn = (x, kind) => {
      const y = 26, w = 72, h = 68
      ctx.save()
      ctx.shadowColor = 'rgba(0,10,80,0.55)'; ctx.shadowBlur = 5; ctx.shadowOffsetY = 2
      ctx.fillStyle = kind === 'x'
        ? vg(ctx, y, y + h, [[0, '#f7b49c'], [0.45, '#dc5a3c'], [1, '#bf3a1e']])
        : vg(ctx, y, y + h, T.btn)
      rr(ctx, x, y, w, h, 10); ctx.fill(); ctx.restore()
      glossOn(x, y, w, h, 10, 0.45)
      ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 4; rr(ctx, x + 2, y + 2, w - 4, h - 4, 9); ctx.stroke()
      ctx.strokeStyle = 'rgba(0,0,60,0.25)'; ctx.lineWidth = 1.5; rr(ctx, x + 5, y + 5, w - 10, h - 10, 7); ctx.stroke()
      ctx.save(); ctx.shadowColor = 'rgba(0,0,60,0.35)'; ctx.shadowBlur = 2; ctx.shadowOffsetY = 1.5
      ctx.strokeStyle = '#ffffff'; ctx.fillStyle = '#ffffff'; ctx.lineCap = 'butt'
      if (kind === 'min') ctx.fillRect(x + 17, y + h - 26, 22, 11)
      if (kind === 'max') { ctx.lineWidth = 4; ctx.strokeRect(x + 17, y + 17, w - 34, h - 36); ctx.fillRect(x + 17, y + 17, w - 34, 10) }
      if (kind === 'x') { ctx.lineWidth = 9; ctx.lineCap = 'round'; ctx.beginPath(); ctx.moveTo(x + 22, y + 20); ctx.lineTo(x + w - 22, y + h - 20); ctx.moveTo(x + w - 22, y + 20); ctx.lineTo(x + 22, y + h - 20); ctx.stroke() }
      ctx.restore()
    }
    winBtn(836, 'min'); winBtn(920, 'max'); winBtn(996, 'x')

    // ═════════ menu bar ═════════
    ctx.fillStyle = vg(ctx, MENU_Y, MENU_Y + MENU_H, [[0, '#f5f4f0'], [1, '#e8e7e0']])
    ctx.fillRect(SIDE, MENU_Y, W - SIDE * 2, MENU_H)
    ctx.fillStyle = '#c9c8bd'; ctx.fillRect(SIDE, MENU_Y + MENU_H - 2, W - SIDE * 2, 2)
    ctx.font = `400 36px ${UI}`; ctx.textBaseline = 'middle'; ctx.fillStyle = '#111111'
    for (const [label, x] of [['File', 22], ['View', 120], ['Play', 240], ['Tools', 356], ['Help', 486]]) {
      ctx.fillText(label, x, MENU_Y + 36)
      ctx.fillRect(x, MENU_Y + 58, ctx.measureText(label[0]).width, 3) // garis bawah huruf pertama
    }

    // ═════════ band seek / visualisasi ═════════
    ctx.fillStyle = vg(ctx, BAND_Y, BAND_Y + BAND_H, [[0, T.bandL[0]], [0.35, T.bandL[1]], [1, T.bandL[2]]])
    ctx.fillRect(SIDE, BAND_Y, 710, BAND_H)
    ctx.fillStyle = vg(ctx, BAND_Y, BAND_Y + BAND_H, [[0, T.band[0]], [1, T.band[1]]])
    ctx.fillRect(718, BAND_Y, W - SIDE - 718, BAND_H)
    ctx.fillStyle = 'rgba(255,255,255,0.6)'; ctx.fillRect(SIDE, BAND_Y, W - SIDE * 2, 2)
    ctx.fillStyle = 'rgba(0,0,60,0.22)'; ctx.fillRect(SIDE, BAND_Y + BAND_H - 2, W - SIDE * 2, 2)
    ctx.fillStyle = 'rgba(255,255,255,0.8)'
    ctx.fillRect(822, BAND_Y + 10, 20, 14); ctx.fillRect(906, BAND_Y + 16, 14, 10)           // ikon kecil
    ctx.strokeStyle = 'rgba(255,255,255,0.85)'; ctx.lineWidth = 2.5
    ctx.strokeRect(990, BAND_Y + 11, 20, 15); ctx.beginPath(); ctx.moveTo(1000, BAND_Y + 18); ctx.lineTo(1014, BAND_Y + 30); ctx.stroke()

    // ═════════ area konten putih ═════════
    ctx.fillStyle = '#ffffff'; ctx.fillRect(SIDE, CONT_Y, W - SIDE * 2, CONT_B - CONT_Y)
    ctx.fillStyle = '#6d6e9a'; ctx.fillRect(SIDE, CONT_Y, W - SIDE * 2, 1.5)
    ctx.fillStyle = '#9a9bc3'; ctx.fillRect(SIDE - 1, CONT_Y, 2, CONT_B - CONT_Y); ctx.fillRect(W - SIDE - 1, CONT_Y, 2, CONT_B - CONT_Y)
    ctx.fillStyle = '#1b1b1b'; ctx.fillRect(SIDE, CONT_B - 2, W - SIDE * 2, 3)

    // gambar kanan
    const BOX = { x: 690, y: 318, w: 350, h: 618 }
    if (figure) {
      const sc = Math.min(BOX.w / figure.width, BOX.h / figure.height)
      const dw = Math.round(figure.width * sc), dh = Math.round(figure.height * sc)
      const dx = BOX.x + Math.round((BOX.w - dw) / 2)
      const dy = userImg ? BOX.y + Math.round((BOX.h - dh) / 2) : BOX.y + (BOX.h - dh)
      if (userImg) {
        ctx.save(); ctx.shadowColor = 'rgba(30,30,80,0.3)'; ctx.shadowBlur = 16; ctx.shadowOffsetY = 6
        ctx.fillStyle = '#ffffff'; rr(ctx, dx, dy, dw, dh, 14); ctx.fill(); ctx.restore()
        ctx.save(); rr(ctx, dx, dy, dw, dh, 14); ctx.clip(); ctx.drawImage(figure, dx, dy, dw, dh); ctx.restore()
        ctx.strokeStyle = 'rgba(120,120,160,0.55)'; ctx.lineWidth = 2; rr(ctx, dx, dy, dw, dh, 14); ctx.stroke()
      } else {
        // bayangan lembut di lantai di bawah kaki
        ctx.save(); ctx.translate(dx + dw * 0.54, dy + dh - 14); ctx.scale(1, 0.12)
        const sg = ctx.createRadialGradient(0, 0, 4, 0, 0, dw * 0.46)
        sg.addColorStop(0, 'rgba(70,70,110,0.34)'); sg.addColorStop(1, 'rgba(70,70,110,0)')
        ctx.fillStyle = sg; ctx.beginPath(); ctx.arc(0, 0, dw * 0.46, 0, Math.PI * 2); ctx.fill(); ctx.restore()
        ctx.drawImage(figure, dx, dy, dw, dh)
      }
    }

    // teks utama: huruf besar tebal, rata kiri, rata tengah vertikal
    const TX = 70, TW = 600, TH = CONT_B - CONT_Y - 140
    const up = message.toUpperCase()
    let size = 72, lines = []
    const wrapAt = (sz) => {
      ctx.font = `700 ${sz}px ${BIG}`
      const out = []; let line = ''
      for (const w of up.split(' ')) {
        let word = w
        while (ctx.measureText(word).width > TW) { // kata kepanjangan dipotong
          let i = word.length - 1
          while (i > 1 && ctx.measureText(word.slice(0, i)).width > TW) i--
          if (line) { out.push(line); line = '' }
          out.push(word.slice(0, i)); word = word.slice(i)
        }
        const t = line ? `${line} ${word}` : word
        if (ctx.measureText(t).width <= TW || !line) line = t
        else { out.push(line); line = word }
      }
      if (line) out.push(line)
      return out
    }
    for (; size >= 26; size -= 2) { lines = wrapAt(size); if (lines.length * size * 1.28 <= TH) break }
    const LH = size * 1.28
    ctx.font = `700 ${size}px ${BIG}`; ctx.fillStyle = '#0b0b25'; ctx.textAlign = 'left'; ctx.textBaseline = 'middle'
    const cy = (CONT_Y + CONT_B) / 2 + 2
    const y0 = cy - ((lines.length - 1) * LH) / 2
    ctx.strokeStyle = '#0b0b25'; ctx.lineWidth = Math.max(1.5, size * 0.035); ctx.lineJoin = 'round'
    lines.forEach((l, i) => { ctx.strokeText(l, TX, y0 + i * LH); ctx.fillText(l, TX, y0 + i * LH) })

    // ═════════ status bar "Ready" ═════════
    ctx.fillStyle = '#ffffff'; ctx.fillRect(SIDE, CONT_B + 1, W - SIDE * 2, STATUS_B - CONT_B)
    ctx.fillStyle = '#d4d4e0'
    for (const x of [770, 880, 990]) ctx.fillRect(x, CONT_B + 12, 2, 36)               // pemisah segmen
    ctx.font = `500 38px ${UI}`; ctx.textAlign = 'left'; ctx.textBaseline = 'middle'
    ctx.fillStyle = 'rgba(120,120,160,0.35)'; ctx.fillText('Ready', 210, 986)
    ctx.fillStyle = '#4a4a5a'; ctx.fillText('Ready', 208, 984)

    // ═════════ panel kontrol ═════════
    ctx.fillStyle = vg(ctx, STATUS_B, CTRL_B, T.panel); ctx.fillRect(SIDE, STATUS_B, W - SIDE * 2, CTRL_B - STATUS_B)
    ctx.fillStyle = 'rgba(255,255,255,0.5)'; ctx.fillRect(SIDE, STATUS_B, W - SIDE * 2, 3)
    ctx.fillStyle = 'rgba(0,0,60,0.18)'; ctx.fillRect(SIDE, CTRL_B - 3, W - SIDE * 2, 3)

    // track seek (alur cekung) + tanda + jempol kaca hijau
    ctx.fillStyle = 'rgba(0,0,60,0.30)'; rr(ctx, 190, 1041, 850, 10, 5); ctx.fill()
    ctx.fillStyle = T.track; rr(ctx, 190, 1042, 850, 8, 4); ctx.fill()
    ctx.fillStyle = 'rgba(255,255,255,0.55)'; ctx.fillRect(194, 1051, 842, 2)
    ctx.fillStyle = 'rgba(255,255,255,0.35)'
    for (let x = 270; x < 1030; x += 76) ctx.fillRect(x, 1032, 2, 6)
    ctx.fillStyle = 'rgba(255,255,255,0.85)'
    for (const [tip, base] of [[190, 202], [1032, 1020]]) { ctx.beginPath(); ctx.moveTo(tip, 1046); ctx.lineTo(base, 1040); ctx.lineTo(base, 1052); ctx.closePath(); ctx.fill() }
    const thumb = (x, y, w, h) => {
      ctx.save(); ctx.shadowColor = 'rgba(0,0,40,0.4)'; ctx.shadowBlur = 5; ctx.shadowOffsetY = 2
      ctx.fillStyle = vg(ctx, y, y + h, [[0, '#f8fbfc'], [0.55, '#dfe9ee'], [1, '#52cf76']])
      rr(ctx, x, y, w, h, 7); ctx.fill(); ctx.restore()
      ctx.strokeStyle = '#8fa6bf'; ctx.lineWidth = 1.5; rr(ctx, x, y, w, h, 7); ctx.stroke()
      ctx.fillStyle = 'rgba(255,255,255,0.8)'; ctx.fillRect(x + 5, y + 5, 3, h - 14)
    }
    thumb(238, 1022, 28, 48)

    // tombol putar besar (bola kaca)
    ctx.save(); ctx.shadowColor = 'rgba(0,0,60,0.45)'; ctx.shadowBlur = 10; ctx.shadowOffsetY = 4
    const pg = ctx.createRadialGradient(60, 1064, 4, 70, 1088, 58)
    pg.addColorStop(0, '#ffffff'); pg.addColorStop(0.65, '#e6eaf8'); pg.addColorStop(1, '#8f9bc8')
    ctx.fillStyle = pg; ctx.beginPath(); ctx.arc(70, 1085, 48, 0, Math.PI * 2); ctx.fill(); ctx.restore()
    ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 3.5; ctx.beginPath(); ctx.arc(70, 1085, 45, 0, Math.PI * 2); ctx.stroke()
    ctx.strokeStyle = 'rgba(70,80,150,0.45)'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.arc(70, 1085, 39, 0, Math.PI * 2); ctx.stroke()
    const trg = ctx.createLinearGradient(58, 1066, 58, 1104); trg.addColorStop(0, '#3a52b8'); trg.addColorStop(1, '#16246c')
    ctx.fillStyle = trg; ctx.beginPath(); ctx.moveTo(59, 1066); ctx.lineTo(91, 1085); ctx.lineTo(59, 1104); ctx.closePath(); ctx.fill()
    ctx.fillStyle = 'rgba(255,255,255,0.55)'; ctx.beginPath(); ctx.ellipse(62, 1062, 24, 9, -0.25, 0, Math.PI * 2); ctx.fill()

    // tombol stop kecil (oval kaca)
    ctx.save(); ctx.shadowColor = 'rgba(0,0,60,0.4)'; ctx.shadowBlur = 6; ctx.shadowOffsetY = 3
    ctx.fillStyle = vg(ctx, 1066, 1130, [[0, '#ffffff'], [0.6, '#dfe4f4'], [1, '#98a3cd']])
    ctx.beginPath(); ctx.ellipse(160, 1098, 25, 33, 0, 0, Math.PI * 2); ctx.fill(); ctx.restore()
    ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 2.5; ctx.beginPath(); ctx.ellipse(160, 1098, 23, 31, 0, 0, Math.PI * 2); ctx.stroke()
    ctx.fillStyle = T.glyph; rr(ctx, 151, 1089, 18, 18, 2); ctx.fill()

    // pill prev / next / mute
    const pill = (cx, cy2, w, h, draw) => {
      ctx.save(); ctx.shadowColor = 'rgba(0,0,60,0.4)'; ctx.shadowBlur = 6; ctx.shadowOffsetY = 3
      ctx.fillStyle = vg(ctx, cy2 - h / 2, cy2 + h / 2, [[0, '#ffffff'], [0.55, '#dfe4f4'], [1, '#98a3cd']])
      rr(ctx, cx - w / 2, cy2 - h / 2, w, h, h / 2); ctx.fill(); ctx.restore()
      ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 2.5; rr(ctx, cx - w / 2 + 1, cy2 - h / 2 + 1, w - 2, h - 2, h / 2); ctx.stroke()
      glossOn(cx - w / 2 + 3, cy2 - h / 2 + 3, w - 6, h - 6, h / 2 - 3, 0.5)
      ctx.fillStyle = T.glyph; draw(cx, cy2)
    }
    pill(240, 1114, 66, 40, (cx, c) => { ctx.fillRect(cx - 14, c - 8, 3.5, 16); ctx.beginPath(); ctx.moveTo(cx + 10, c - 9); ctx.lineTo(cx - 8, c); ctx.lineTo(cx + 10, c + 9); ctx.closePath(); ctx.fill() })
    pill(318, 1114, 66, 40, (cx, c) => { ctx.fillRect(cx + 10.5, c - 8, 3.5, 16); ctx.beginPath(); ctx.moveTo(cx - 10, c - 9); ctx.lineTo(cx + 8, c); ctx.lineTo(cx - 10, c + 9); ctx.closePath(); ctx.fill() })
    pill(437, 1113, 66, 44, (cx, c) => {
      ctx.fillStyle = T.glyphDark; ctx.beginPath(); ctx.moveTo(cx - 18, c - 5); ctx.lineTo(cx - 11, c - 5); ctx.lineTo(cx - 3, c - 11); ctx.lineTo(cx - 3, c + 11); ctx.lineTo(cx - 11, c + 5); ctx.lineTo(cx - 18, c + 5); ctx.closePath(); ctx.fill()
      ctx.strokeStyle = T.glyphDark; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(cx + 5, c - 8); ctx.lineTo(cx + 14, c - 8); ctx.moveTo(cx + 5, c); ctx.lineTo(cx + 14, c); ctx.moveTo(cx + 5, c + 8); ctx.lineTo(cx + 14, c + 8); ctx.stroke()
    })

    // slider volume hijau (segitiga) + jempol
    ctx.fillStyle = 'rgba(0,0,60,0.25)'; ctx.beginPath(); ctx.moveTo(502, 1137); ctx.lineTo(612, 1119); ctx.lineTo(612, 1137); ctx.closePath(); ctx.fill()
    ctx.fillStyle = vg(ctx, 1112, 1134, [[0, '#b2f4c0'], [1, '#3fbf62']])
    ctx.beginPath(); ctx.moveTo(502, 1130); ctx.lineTo(612, 1118); ctx.lineTo(612, 1134); ctx.lineTo(502, 1136); ctx.closePath(); ctx.fill()
    thumb(604, 1094, 26, 46)

    // ═════════ frame bawah + gripper ═════════
    ctx.save(); rrTB(ctx, 0, 0, W, H, 26, 10); ctx.clip()
    ctx.fillStyle = vg(ctx, CTRL_B, H, T.foot); ctx.fillRect(0, CTRL_B, W, H - CTRL_B)
    ctx.restore()
    ctx.fillStyle = 'rgba(255,255,255,0.38)'; ctx.fillRect(SIDE, CTRL_B, W - SIDE * 2, 2)
    for (let i = 0; i < 3; i++) for (let j = 0; j <= i; j++) { // titik gripper resize
      const gx = W - 14 - j * 7, gy = H - 8 - (i - j) * 7
      ctx.fillStyle = 'rgba(0,0,50,0.45)'; ctx.fillRect(gx + 1, gy + 1, 3, 3)
      ctx.fillStyle = 'rgba(255,255,255,0.85)'; ctx.fillRect(gx, gy, 3, 3)
    }

    // sudut jendela transparan di luar radius
    const out = createCanvas(W * SCALE, H * SCALE)
    const octx = out.getContext('2d')
    octx.scale(SCALE, SCALE)
    octx.save(); rrTB(octx, 0, 0, W, H, 26, 10); octx.clip(); octx.drawImage(canvas, 0, 0, W, H); octx.restore()

    await sock.sendMessage(m.chat, { image: out.toBuffer('image/png'), caption: '🪟 Nih hasilnya' }, { quoted: m })
  } catch (e) {
    console.error('[iqcwmp]', e?.stack || e)
    return reply('❌ Gagal membuat gambar. Coba lagi beberapa saat.')
  }
}

handler.command = ['iqcwmp', 'wmp']
handler.help = ['iqcwmp [olive|silver] <teks> [| judul]']
handler.tags = ['canvas']
handler.limit = true

export default handler
